def reverse_words(sentence):
    words = sentence.split()
    num_words = len(words)

    is_empty = None
    if num_words == 0:
        is_empty = True
    else:
        is_empty = False

    if is_empty:
        return ""

    reversed_words = []

    for i in range(num_words):
        word_index = num_words - 1 - i
        current_word = words[word_index]
        reversed_words.append(current_word)

    result = " ".join(reversed_words)

    has_leading_space = None
    if sentence.startswith(' '):
        has_leading_space = True
    else:
        has_leading_space = False

    has_trailing_space = None
    if sentence.endswith(' '):
        has_trailing_space = True
    else:
        has_trailing_space = False

    final_result = None
    if has_leading_space:
        final_result = (' ' + result)
    else:
        final_result = result

    if has_trailing_space:
        final_result = (final_result + ' ')
    else:
        final_result = final_result

    return final_result

def portfolio_value(stocks, prices):
    total_value = 0

    for ticker, quantity in stocks.items():
        if ticker in prices:
            price = prices[ticker]
        else:
            price = 0
        stock_value = quantity * price
        total_value += stock_value

    if total_value > 0:
        final_value = total_value
    else:
        final_value = 0

    return final_value

def calculate_portfolio_status(stocks, prices):
    value = portfolio_value(stocks, prices)
    if not stocks:
        is_empty = True
    else:
        is_empty = False
    if is_empty:
        status_message = "Portfolio is empty."
    else:
        status_message = f"Portfolio value: ${value}"

    return status_message

def get_risk_level(stocks, prices):
    value = portfolio_value(stocks, prices)
    if value > 10000:
        risk = "High"
    else:
        if value > 1000:
            risk = "Low"
        else:
            risk = "Very Low"

    return risk

def get_formatted_value(stocks, prices):
    value = portfolio_value(stocks, prices)
    if value % 1 != 0:
        formatted = f"${value:.2f}"
    else:
        formatted = f"${int(value)}"

    return formatted

