    missing_tickers = [ticker for ticker in stocks if ticker not in prices]
    if missing_tickers:
        has_missing = True
    else:
        has_missing = False
    if not has_missing:
        message = "All prices available."
    else:
        message = f"Missing prices for: {', '.join(missing_tickers)}"

    return message

