def run_length_encode(s):
    if not s:
        return ""

    encoded_string = []
    current_char = s[0]
    count = 0

    for i in range(len(s)):
        is_same_char = (s[i] == current_char)
        if is_same_char:
            count = count + 1
        else:
            count = 1

        should_append = (not is_same_char) or (i == len(s) - 1)

        if should_append:
            if not is_same_char:
                char_to_append = current_char
            else:
                char_to_append = s[i]
            if not is_same_char:
                count_to_append = count - 1
            else:
                count_to_append = count

            encoded_string.append(char_to_append + str(count_to_append))

            if not is_same_char:
                current_char = s[i]
            else:
                current_char = current_char
            if not is_same_char:
                count = 1
            else:
                count = count

    if encoded_string:
        final_result = "".join(encoded_string)
    else:
        final_result = ""
